{"index":{"ready":true,"state":"ready","bootstrap_complete":true,"indexed_revision":8340,"target_revision":8340,"revision":"8340","last_synced":"2026-11-16T15:05:25Z"},"provenance":"deterministic","nodes":[{"name":"SanitizeInstance","kind":"function","path":"entityid/entityid.go","lines":[318,347],"body":"func SanitizeInstance(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	for _, r := range s {
		if isAllowedInstanceRune(r) {
			b.WriteRune(r)
		} else {
			b.WriteRune('-')
		}
	}
	out := b.String()
	for strings.Contains(out, "--") {
		out = strings.ReplaceAll(out, "--", "-")
	}
	out = strings.TrimFunc(out, func(r rune) bool { return !isASCIIAlnum(r) })

	if out == "" {
		return shortHash(s)
	}
	if len(out) > maxInstanceLen {
		suffix := shortHash(s)
		prefix := strings.TrimRightFunc(out[:maxInstanceLen-len(suffix)-1],
			func(r rune) bool { return !isASCIIAlnum(r) })
		if prefix == "" {
			return suffix
		}
		return prefix + "-" + suffix
	}
	return out
