	g := fusiontest.NewMemGraph()
	store := fusiontest.NewMemStore()
	body := "# Retry Policy\n\nUse exponential backoff with jitter."
	store.Set("body:retry", body)

	id := "o.semsource.web.s.doc.abc123"
	g.AddEntity(id, map[string]any{
		source.DocType:          "document",
		source.DcTitle:          "Retry Policy",
		source.DocFilePath:      "docs/retry.md",
		source.DocBodyStore:     "objectstore",
		source.DocBodyKey:       "body:retry",
		ontology.ClassPredicate: cco.MaterialCopyOfDocument,
	})
	g.SetResolve("how does retry work", id)

	engine, err := fusion.NewEngine(g, fusion.NewBodyResolver(fusion.MapStoreResolver{"objectstore": store}), slog.Default())
	if err != nil {
		t.Fatal(err)
	}
	resp, err := engine.Fuse(context.Background(),
		fusion.Request{Query: "how does retry work", Want: []fusion.Want{fusion.WantBody}},
		New())
	if err != nil {
		t.Fatal(err)
	}
	if len(resp.Nodes) != 1 {
		t.Fatalf("expected 1 doc node, got %d", len(resp.Nodes))
	}
	n := resp.Nodes[0]
	if n.Name != "Retry Policy" || n.Kind != "document" || n.Body != body || n.Path != "docs/retry.md" {
		t.Fatalf("doc node mismatch: %+v", n)
	}
	if n.Class != cco.MaterialCopyOfDocument {
		t.Fatalf("expected MaterialCopyOfDocument class, got %q", n.Class)
	}
	// NL query → word-index resolve → lexical provenance (semengine alpha.5).
	if resp.Provenance != fusion.ProvenanceLexical {
		t.Fatalf("expected lexical provenance for NL doc query, got %q", resp.Provenance)
	}
}","class":"http://www.ontologyrepository.com/CommonCoreOntologies/Algorithm","handle":"c360.semsource-9da70e.workspace.golang.function.source-fusion-lens-docs-docs_test-go-TestDocsLensViaEngine"},{"name":"error","kind":"var","path":"ui/src/lib/api/search.test.ts","lines":[108,108],"body":"    let error: unknown;","class":"http://www.ontologyrepository.com/CommonCoreOntologies/SoftwareCode","handle":"c360.semsource-9da70e.workspace.typescript.var.ui-src-lib-api-search-test-ts-error"},{"name":"enterBackpressure","kind":"method","path":"internal/entitypub/publisher.go","lines":[379,388],"body":"func (p *Publisher) enterBackpressure(entityID string, backoff time.Duration) {
